#!/usr/bin/env python3
"""Make rosbag2 metadata generated by newer ROS distros playable on Humble."""

import argparse
from pathlib import Path

import yaml


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("bag", type=Path, help="Bag directory containing metadata.yaml")
    args = parser.parse_args()
    metadata_path = args.bag / "metadata.yaml"
    metadata = yaml.safe_load(metadata_path.read_text(encoding="utf-8"))
    information = metadata["rosbag2_bagfile_information"]
    information["version"] = 5
    information.pop("custom_data", None)
    information.pop("ros_distro", None)
    for topic in information["topics_with_message_count"]:
        topic_metadata = topic["topic_metadata"]
        topic_metadata["offered_qos_profiles"] = ""
        topic_metadata.pop("type_description_hash", None)
    metadata_path.write_text(
        yaml.safe_dump(metadata, sort_keys=False), encoding="utf-8"
    )


if __name__ == "__main__":
    main()
